#
# Phiên bản này KHÔNG dùng keyword để tự đoán nhóm nữa.
# Chương trình chỉ phân loại khi tên phương pháp trong file HIS khớp với
# danh sách PHAN_LOAI_PHUONG_PHAP_UU_TIEN bên dưới.
#
# Cách chỉnh:
# - Muốn đổi nhóm: đổi giá trị "nhom" của đúng tên kỹ thuật.
# - Muốn thêm kỹ thuật mới: thêm một dòng vào PHAN_LOAI_PHUONG_PHAP_UU_TIEN.
# - kieu_khop="chinh_xac": tên kỹ thuật phải khớp đúng sau khi chuẩn hóa.
# - kieu_khop="chua_cum_tu": chỉ dùng khi thật sự muốn bắt theo cụm từ.
#
# Lưu ý:
# - Danh sách này đã được bổ sung từ file cphan_loai_T1_den_T5_2026_chi_tiet.xlsx.
# - Các dòng bạn đã tự phân loại được giữ nguyên.
# - Các dòng còn trống đã được bổ sung nhóm đề xuất để code tự phân loại.

